// CarView is the resolver for the carView field.
//
// A window of the city around one car. This is the cheap poll an agent or a
// client with a large map wants: it returns the local terrain, the cars in
// view and the nearby open orders instead of the whole snapshot.
func (r *queryResolver) CarView(ctx context.Context, id string, carID string, radius int) (*model.CarWindow, error) {
	sess, err := r.load(id)
	if err != nil {
		return nil, err
	}
	if radius < 0 {
		return nil, errBadInput("radius must be >= 0")
	}
	if radius > 10 {
		radius = 10
	}

	snap := sess.Snapshot()
	var car *session.CarView
	for i := range snap.Cars {
		if snap.Cars[i].ID == carID {
			car = &snap.Cars[i]
			break
		}
	}
	if car == nil {
		return nil, errNotFound("no car " + carID)
	}

	size := snap.City.GridSize
	x0, y0 := car.X-radius, car.Y-radius
	x1, y1 := car.X+radius, car.Y+radius
	if x0 < 0 {
		x0 = 0
	}
	if y0 < 0 {
		y0 = 0
	}
	if x1 > size-1 {
		x1 = size - 1
	}
	if y1 > size-1 {
		y1 = size - 1
	}

	rows := make([]string, 0, y1-y0+1)
	for y := y0; y <= y1; y++ {
		row := snap.City.Rows[y]
		// The row is a byte per tile in ASCII; slice by rune to stay safe if the
		// glyph set ever grows beyond ASCII.
		r := []rune(row)
		rows = append(rows, string(r[x0:min(x1+1, len(r))]))
	}

	visibleCars := make([]*model.CarView, 0, len(snap.Cars))
	for _, c := range snap.Cars {
		if c.X >= x0 && c.X <= x1 && c.Y >= y0 && c.Y <= y1 {
			visibleCars = append(visibleCars, carFrom(c))
		}
	}

	// Nearby orders: open ones whose kitchen or customer is inside the window.
	posOf := map[string]session.PointView{}
	for _, p := range snap.City.Kitchens {
		posOf[p.ID] = p
	}
	for _, p := range snap.City.Customers {
		posOf[p.ID] = p
	}
	inWindow := func(id string) bool {
		p, ok := posOf[id]
		if !ok {
			return false
		}
		return p.X >= x0 && p.X <= x1 && p.Y >= y0 && p.Y <= y1
	}

	nearby := make([]*model.OrderView, 0)
	for _, o := range snap.Orders {
		if o.State == "done" || o.State == "expired" {
			continue
		}
		if inWindow(o.KitchenID) || inWindow(o.CustomerID) {
			nearby = append(nearby, orderFrom(o))
		}
	}

	return &model.CarWindow{
		Car:          carFrom(*car),
		RowSpan:      y1 - y0 + 1,
		ColSpan:      x1 - x0 + 1,
		Rows:         rows,
		OriginX:      x0,
		OriginY:      y0,
		VisibleCars:  visibleCars,
		NearbyOrders: nearby,
	}, nil
}

